/* Continuous one-page study layout */
.code-all-steps {padding:12px 22px 20px;background:var(--paper)}
.code-all-step {border-bottom:1px solid var(--line);padding:14px 0 8px}
.code-all-step:last-child {border-bottom:none}
.code-all-step p {font-size:13px;line-height:1.8;margin:8px 0}
.code-all-step .step-heading {display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px}
.code-all-step .step-heading h4 {margin:0;font-size:14px}
.code-all-step .step-heading span {font-size:10px;color:var(--muted)}
html {scroll-behavior:smooth}
#welcome, .onepage-track, article[data-lesson], #exam, #lecture, #lab {scroll-margin-top:90px}
.onepage-nav {padding-bottom:12px}
.onepage-nav .nav-section-link {display:block;width:100%;text-align:left;border:1px solid var(--line);background:var(--paper);padding:11px 12px;border-radius:10px;color:var(--ink);font-weight:700;margin:0 0 16px;cursor:pointer}
.onepage-nav .nav-track-title {font:750 11px/1.5 system-ui,sans-serif;letter-spacing:1.2px;color:var(--accent);padding:15px 9px 7px;border-top:1px solid var(--line);margin-top:10px}
.onepage-nav .nav-group-caption {font-size:11px;font-weight:700;color:var(--muted);padding:10px 12px 4px}
.onepage-nav .nav-link {width:100%;margin:1px 0;min-height:35px}
.onepage-nav .exam-nav {width:100%;margin:12px 0}
.onepage-track-heading {padding-top:64px;padding-bottom:18px}
.onepage-track-heading h1 {font-size:clamp(30px,4vw,43px);font-weight:700;margin:12px 0;color:var(--ink);line-height:1.35}
.onepage-track-heading p {color:var(--muted);font-size:16px;line-height:1.8}
.onepage-note {background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:23px 28px}
.onepage-note b {font-size:20px;display:block;margin:8px 0}
.onepage-note p {font-size:14px;line-height:1.8;color:var(--muted);margin:0}
.onepage-welcome .home-page {padding-bottom:22px}
.onepage-track .lesson-page {padding-top:48px;padding-bottom:65px;border-bottom:1px solid var(--line);position:relative}
.onepage-track .lesson-page:nth-of-type(even) {background:color-mix(in srgb,var(--paper) 24%,transparent)}
.onepage-track .chapter-heading {padding-top:5px}
.onepage-track .complete-row {margin-bottom:0}
.onepage-exam {padding-top:85px;padding-bottom:95px}
.onepage-exam .exam-heading {margin-bottom:25px}
.onepage-exam .exam-part-heading {margin:46px 0 20px;padding:20px 0 8px;border-bottom:2px solid var(--line)}
.onepage-exam .exam-part-heading span {font:750 11px/1.4 system-ui,sans-serif;color:var(--accent);letter-spacing:1.6px}
.onepage-exam .exam-part-heading h2 {font-size:25px;line-height:1.5;margin:6px 0 0}
.onepage-exam .question-paper {margin:0 0 17px;padding:30px 32px;scroll-margin-top:90px}
.onepage-exam .question-paper h2 {font-size:19px;line-height:1.7}
.onepage-exam .answer-fieldset {border:0;padding:0;margin:0;min-width:0}
.onepage-exam .exam-statusbar {margin-bottom:15px}
.onepage-exam .long-exam-actions,.onepage-exam .exam-result-actions {display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin:14px 0 24px}
.onepage-exam .exam-result-actions.bottom {margin-top:36px}
.onepage-exam .long-submit {position:relative;margin-top:45px}
.onepage-exam .question-reference {font-size:12px}
.onepage-exam .question-reference button {text-align:left;color:var(--accent);font-size:12px}
.onepage-end {text-align:center;padding-top:0;padding-bottom:85px}
.onepage-end b {font-size:20px}
.onepage-end p {color:var(--muted);font-size:14px}
.onepage-track .lesson-toc h2 {scroll-margin-top:100px}
@media(max-width:760px) {
  .onepage-track-heading {padding-top:40px}
  .onepage-track .lesson-page {padding-top:36px;padding-bottom:44px}
  .onepage-exam {padding-top:50px;padding-bottom:55px}
  .onepage-exam .question-paper {padding:19px 17px;margin-bottom:13px}
  .onepage-exam .question-paper h2 {font-size:17px}
  .onepage-exam .exam-part-heading h2 {font-size:20px}
  .onepage-note {padding:18px}
}
@media print { .onepage-track .lesson-page {break-before:page; background:transparent!important} .onepage-exam .question-paper {break-inside:avoid} }
