          return chapters.length ? '<div class="nav-group-caption">' + esc(group.label) + '</div>' +
            chapters.map((item, index) => '<button data-go="' + item.id + '" class="nav-link ' + track + (state.done[item.id] ? ' done' : '') + (current === item.id ? ' active' : '') + '"><span class="nav-index">' + (state.done[item.id] ? '✓' : String(items.indexOf(item) + 1).padStart(2, '0')) + '</span><span class="nav-label">' + esc(item.title) + '</span></button>').join('') : '';
        }).join('');
