// Main material always stays mounted; only the 302-page PDF reference reader
// uses its old separate view so embedded page images are not decoded en masse.
function longExamQuestionHTML(q) {
  const e = state.exam, answer = e.answers[q.id], number = +q.id.slice(1);
  return '<section class="question-paper long-question" id="question-' + q.id + '" data-question="' + q.id + '" aria-labelledby="question-title-' + q.id + '">' +
    '<div class="question-topline"><span class="tag ' + q.track + '">' + q.track.toUpperCase() + '</span><span>' + esc(GROUPS[q.topic].label) + '</span><span>' + esc(q.kind) + ' · ข้อ ' + number + '</span></div>' +
    '<h2 id="question-title-' + q.id + '">' + number + '. ' + esc(q.prompt) + '</h2>' + (q.code ? '<pre class="exam-code"><code>' + esc(q.code) + '</code></pre>' : '') +
    '<fieldset class="answer-fieldset"><legend class="sr-only">คำตอบข้อ ' + number + '</legend><div class="answer-list">' + q.options.map((option, i) => {
      const chosen = answer === i, correct = q.answer === i;
      return '<label class="answer-option ' + (chosen ? 'selected ' : '') + (e.submitted ? (correct ? 'correct-answer' : chosen ? 'wrong-answer' : '') : '') + '">' +
        '<input type="radio" name="exam-answer-' + q.id + '" value="' + i + '" ' + (chosen ? 'checked ' : '') + (e.submitted ? 'disabled ' : '') + '><span class="answer-letter">' + 'ABCD'[i] + '</span><span style="flex:1">' + esc(option.text) +
        (e.submitted ? '<div class="option-feedback">' + (correct ? '<span class="answer-verdict">คำตอบที่ถูก' + (chosen ? ' · คุณตอบถูก' : '') + '</span>' : chosen ? '<span class="answer-verdict">ตัวเลือกที่ตอบ</span>' : '') + esc(option.why) + '</div>' : '') + '</span></label>';
    }).join('') + '</div></fieldset>' +
    (e.submitted ? '<div class="widget-result question-reference"><b>กลับไปอ่านเนื้อหาที่เกี่ยวข้อง</b><br><button class="quiet" data-go="' + q.lesson + '">' + esc(BY_ID[q.lesson]?.title || 'บทเรียน') + ' ↗</button></div>' : '<div class="question-foot"><label><input type="checkbox" data-exam-flag ' + (e.flags[q.id] ? 'checked' : '') + '> ปักหมุดกลับมาทบทวน</label></div>') +
    '</section>';
}
function longExamHTML() {
  const e = state.exam, summary = examSummary(QUESTIONS, e.answers);
  return '<div class="exam-heading"><div><span class="eyebrow">03 / 100 QUESTIONS · SCROLL TO ANSWER</span><h1>ข้อสอบฝึก 100 ข้อ</h1><p class="deck">รวม Lecture 50 ข้อ และ Lab 50 ข้อ ทุกข้อเรียงต่อกันในหน้าเดียว ไม่ต้องกดข้อถัดไป</p></div><div class="exam-seal">100<small>QUESTIONS</small></div></div>' +
    (e.submitted ? scoreHTML(summary) + '<div class="exam-result-actions"><button class="secondary" data-long-new>เริ่มทำใหม่</button><button class="quiet" data-exam-print>พิมพ์พร้อมเฉลย</button></div>' :
      '<div class="exam-statusbar"><div><b data-long-count>ตอบแล้ว ' + summary.answered + ' / 100 ข้อ</b><div class="mini-meter"><i data-long-meter style="width:' + summary.answered + '%"></i></div></div><span>เลือกคำตอบได้ทุกข้อ · บันทึกอัตโนมัติในเครื่องนี้</span></div>' +
      '<div class="long-exam-actions"><button class="quiet" data-exam-print>พิมพ์ข้อสอบ</button><button class="secondary" data-long-new>ล้างคำตอบ / เริ่มใหม่</button></div>') +
    ['lecture', 'lab'].map(track => '<div class="exam-part-heading"><span>' + (track === 'lecture' ? 'PART 01 / LECTURE' : 'PART 02 / LAB') + '</span><h2>' + (track === 'lecture' ? 'แนวคิดและการวิเคราะห์' : 'โค้ด การคำนวณ และการประยุกต์') + ' · 50 ข้อ</h2></div>' + QUESTIONS.filter(q => q.track === track).map(longExamQuestionHTML).join('')).join('') +
    (!e.submitted ? '<div class="submit-row long-submit"><p>ตรวจคำตอบได้เมื่อทำเสร็จ · ข้อที่ไม่ตอบนับเป็น 0 คะแนน</p><button class="primary" data-long-submit>ส่งคำตอบและดูเฉลยทั้งหมด</button></div>' : '<div class="exam-result-actions bottom"><button class="secondary" data-long-new>เริ่มรอบใหม่</button><button data-go="lecture" class="quiet">กลับไปทบทวน Lecture ↑</button></div>');
}
function bindLongExam() {
  const root = document.getElementById('exam');
  root.addEventListener('change', event => {
    const section = event.target.closest('[data-question]'); if (!section) return;
    const qid = section.dataset.question;
    if (event.target.matches('input[type="radio"]') && !state.exam.submitted) {
      state.exam.answers[qid] = +event.target.value;
      $$('.answer-option', section).forEach(label => label.classList.toggle('selected', $('input', label).checked));
      const summary = examSummary(QUESTIONS, state.exam.answers);
      const count = $('[data-long-count]', root), meter = $('[data-long-meter]', root);
      if (count) count.textContent = 'ตอบแล้ว ' + summary.answered + ' / 100 ข้อ';
      if (meter) meter.style.width = summary.answered + '%';
      save();
    }
    if (event.target.hasAttribute('data-exam-flag')) { state.exam.flags[qid] = event.target.checked; save(); }
  });
  root.addEventListener('click', event => {
    const btn = event.target.closest('button'); if (!btn) return;
    if (btn.hasAttribute('data-long-submit')) {
      const summary = examSummary(QUESTIONS, state.exam.answers), missing = QUESTIONS.length - summary.answered;
      if (missing) confirmAction('ยังไม่ได้ตอบ ' + missing + ' ข้อ', 'ส่งตอนนี้ได้ โดยข้อที่ยังไม่ตอบจะได้ 0 คะแนน หรือกลับไปตอบให้ครบก่อน', submitLongExam, 'ส่งคำตอบ');
      else submitLongExam();
    }
    if (btn.hasAttribute('data-long-new')) {
      confirmAction('เริ่มทำข้อสอบรอบใหม่?', 'คำตอบเดิมจะถูกล้าง แต่คะแนนที่เคยส่งแล้วจะอยู่ในประวัติ', () => {
        const old = state.exam;
        state.exam = {mode:'all', answers:{}, flags:{}, started:true, submitted:false, current:0, history:old.history || []};
        renderLongExam(); root.scrollIntoView({behavior:'smooth', block:'start'});
      }, 'เริ่มทำใหม่');
    }
    if (btn.hasAttribute('data-exam-print')) printExam();
  });
}
function renderLongExam() {
  document.getElementById('exam').innerHTML = longExamHTML();
  save(); updateReadingProgress();
}
function submitLongExam() {
  state.exam.submitted = true;
  const summary = examSummary(QUESTIONS, state.exam.answers);
  state.exam.history.push({mode:'all', correct:summary.correct, total:100, at:new Date().toISOString()});
  state.exam.history = state.exam.history.slice(-5);
  renderLongExam();
  document.getElementById('exam').scrollIntoView({behavior:'smooth', block:'start'});
}
function longPageHTML() {
  return '<div id="welcome" class="onepage-welcome">' + homeHTML(BY_ID.start) + '</div>' +
    '<div class="onepage-intro page"><div class="onepage-note"><span class="eyebrow">ONE PAGE / CONTINUOUS READING</span><b>ทุกบทอยู่ต่อกันในหน้านี้</b><p>เลื่อนลงเพื่ออ่าน Lecture ทั้งหมด แล้วต่อด้วย Lab และข้อสอบ 100 ข้อ ใช้สารบัญด้านซ้ายเพื่อกระโดดไปยังบทที่ต้องการได้ทันที</p></div></div>' +
    ['lecture', 'lab'].map(track => '<section class="onepage-track" id="' + track + '"><header class="onepage-track-heading page"><span class="eyebrow">' + (track === 'lecture' ? 'PART 01 / THEORY' : 'PART 02 / PRACTICE') + '</span><h1>' + (track === 'lecture' ? 'Lecture · ทฤษฎีและเหตุผล' : 'Lab · โค้ดและการทดลอง') + '</h1><p>' + (track === 'lecture' ? 'อ่านเรียงต่อเนื่องจากพื้นฐานจนถึงการนำไปใช้' : 'ต่อจากทฤษฎีด้วยตัวอย่างโค้ดและการอธิบายทีละขั้น') + '</p></header>' +
      LESSONS.filter(x => x.track === track).map(item => lessonHTML(item).replace('<article class="page lesson-page"', '<article id="' + item.id + '" data-lesson="' + item.id + '" class="page lesson-page"')).join('') + '</section>').join('') +
    '<section class="page exam-page onepage-exam" id="exam">' + longExamHTML() + '</section><div class="page onepage-end"><b>อ่านครบทั้ง Lecture, Lab และข้อสอบแล้ว</b><p>สามารถกลับไปทบทวนบทต่าง ๆ ได้จากสารบัญด้านซ้าย หรือใช้ค้นหาบทเรียน</p><button class="secondary" data-go="welcome">กลับไปด้านบน ↑</button></div>';
}
function setActiveSection(id) {
  if (!BY_ID[id] && id !== 'exam' && id !== 'welcome' && id !== 'lecture' && id !== 'lab') return;
  current = id;
  if (BY_ID[id]) { state.last = id; state.track = BY_ID[id].track; state.lastTrack[state.track] = id; }
  $('#breadcrumb').textContent = id === 'exam' ? 'ข้อสอบฝึก 100 ข้อ' : id === 'welcome' ? 'ภาพรวม' : BY_ID[id]?.title || (id === 'lab' ? 'Lab' : 'Lecture');
  refreshNavHighlight();
}
let chapterObserver;
function observeLongPage() {
  chapterObserver?.disconnect();
  chapterObserver = new IntersectionObserver(entries => {
    if (document.querySelector('#main')?.dataset.onepage !== '1') return;
    const found = entries.filter(e => e.isIntersecting).sort((a,b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
    if (found) setActiveSection(found.target.id);
  }, {rootMargin:'-12% 0px -73% 0px', threshold:0});
  $$('#welcome,article[data-lesson],#exam').forEach(el => chapterObserver.observe(el));
}

if (document.querySelector('#main')?.dataset.onepage === '1' && document.getElementById(id)) {
  history.pushState(null, '', '#' + id);
  setActiveSection(id);
  document.getElementById(id).scrollIntoView({behavior:'smooth', block:'start'});
  save();
} else {
  if (location.hash.slice(1) === id) renderRoute();
  else location.hash = id;
}

const sourceMode = isArchiveRoute(requested);
chapterObserver?.disconnect();
if (sourceMode) {
  current = requested;
  $('#main').dataset.onepage = '0';
  $('#main').innerHTML = requested === 'full' ? archiveHubHTML() : archivePageHTML();
  $('#breadcrumb').textContent = 'เอกสาร PDF ต้นฉบับ';
  document.title = archivePageTitle() + ' · AI Fieldnotes';
  renderNav(); bindArchive();
  window.scrollTo({top:0, behavior:'instant'});
} else {
  if ($('#main').dataset.onepage !== '1') {
    state.exam.mode = 'all'; state.exam.started = true;
    $('#main').innerHTML = longPageHTML();
    $('#main').dataset.onepage = '1';
    mountCodes(); mountWidgets(); bindLongExam();
  }
  const id = document.getElementById(requested) ? requested : 'welcome';
  setActiveSection(id); renderNav(); observeLongPage();
  document.title = 'AI Fieldnotes · Lecture, Lab และข้อสอบครบในหน้าเดียว';
  requestAnimationFrame(() => {
    if (requested && requested !== 'welcome' && document.getElementById(id))
      document.getElementById(id).scrollIntoView({behavior:'instant', block:'start'});
    else window.scrollTo({top:0, behavior:'instant'});
    updateReadingProgress();
  });
}
save();

function codeHTML(code, stepIndex, all = true) {
  const lines = code.code.split("\n");
  return '<div class="code-top"><div class="code-title"><small>CODE WALKTHROUGH · ' + (code.lang === "colab" ? "COLAB / PYTHON" : "PYTHON") + '</small>' + esc(code.title) + '</div><button class="copy-button" data-copy aria-label="คัดลอกโค้ดทั้งชุด">' + icon('copy') + '<span>คัดลอก</span></button></div>' +
    '<div class="code-viewport" tabindex="0" role="region" aria-label="โค้ด ' + esc(code.title) + '"><pre class="code-lines"><code>' +
    lines.map((line, i) => '<span class="code-line"><span class="line-number" aria-hidden="true">' + (i + 1) + '</span>' + highlightPython(line || ' ') + '</span>').join('') +
    '</code></pre></div><div class="code-mode"><span>โค้ดครบทั้ง ' + lines.length + ' บรรทัด</span><span>คำอธิบายทุกช่วงอยู่ด้านล่าง ↓</span></div>' +
    '<div class="code-all-steps">' + code.steps.map((step, i) => '<section class="code-all-step"><div class="step-heading"><h4>' + esc(step.title) + '</h4><span>STEP ' + (i + 1) + '/' + code.steps.length + ' · บรรทัด ' + step.start + '–' + step.end + '</span></div><p>' + esc(step.body) + '</p></section>').join('') + '</div>';
